themes.lightCss:
@plugin "daisyui/theme" {
  name: "seotool-light";
  default: true;
  prefersdark: false;
  color-scheme: light;
  --color-base-100: oklch(98.5% 0.008 247);
  --color-base-200: oklch(96% 0.016 247);
  --color-base-300: oklch(91% 0.028 252);
  --color-base-content: oklch(19% 0.035 262);
  --color-primary: oklch(70% 0.17 178);
  --color-primary-content: oklch(16% 0.03 262);
  --color-secondary: oklch(58% 0.22 278);
  --color-secondary-content: oklch(98% 0.004 247);
  --color-accent: oklch(68% 0.19 230);
  --color-accent-content: oklch(16% 0.03 262);
  --color-neutral: oklch(22% 0.04 262);
  --color-neutral-content: oklch(98% 0.004 247);
  --color-info: oklch(74% 0.15 215);
  --color-info-content: oklch(16% 0.03 262);
  --color-success: oklch(70% 0.15 165);
  --color-success-content: oklch(16% 0.03 262);
  --color-warning: oklch(80% 0.16 85);
  --color-warning-content: oklch(22% 0.04 70);
  --color-error: oklch(63% 0.23 25);
  --color-error-content: oklch(98% 0.004 247);
  --radius-selector: 0.75rem;
  --radius-field: 0.75rem;
  --radius-box: 1.5rem;
  --size-selector: 0.25rem;
  --size-field: 0.25rem;
  --border: 1px;
  --depth: 0;
  --noise: 0;
}

